const caseRow = $input.first().json;
const trigger = $('Batch Document Check Trigger').first().json;
let files = [];

if (trigger.files_json) {
  const parsed = typeof trigger.files_json === 'string' ? JSON.parse(trigger.files_json) : trigger.files_json;
  files = Array.isArray(parsed) ? parsed : (parsed.files || []);
}

const uploadSubfolder = trigger.upload_subfolder || '02_Identity_Documents';
return [{
  json: {
    case_id: Number(trigger.case_id || caseRow.case_id),
    applicant_id: trigger.applicant_id || caseRow.applicant_id,
    primary_contact_name: caseRow.primary_contact_name,
    primary_contact_email: caseRow.primary_contact_email,
    folder_root_id: trigger.folder_root_id || caseRow.folder_root_id,
    source_drive_id: trigger.source_drive_id || $env.SHAREPOINT_DRIVE_ID,
    folder_item_id: trigger.folder_item_id || '',
    folder_path: trigger.folder_path || '',
    upload_subfolder: uploadSubfolder,
    source: trigger.source || 'manual_batch',
    files,
    has_provided_files: files.length > 0
  }
}];

const req = $input.first().json;
return req.files.map(f => ({
  json: {
    case_id: req.case_id,
    applicant_id: req.applicant_id,
    file_id: f.file_id || f.id,
    file_name: f.file_name || f.name,
    file_mime_type: f.file_mime_type || f.mimeType || f.file?.mimeType || 'application/octet-stream',
    file_size: Number(f.file_size || f.size || 0),
    source_drive_id: req.source_drive_id,
    source: req.source
  }
})).filter(i => i.json.file_id && i.json.file_name);

const req = $('Prepare Batch Request').first().json;
const listed = $input.first().json.value || [];
return listed
  .filter(f => f.file && !f.deleted)
  .map(f => ({
    json: {
      case_id: req.case_id,
      applicant_id: req.applicant_id,
      file_id: f.id,
      file_name: f.name,
      file_mime_type: f.file?.mimeType || 'application/octet-stream',
      file_size: Number(f.size || 0),
      source_drive_id: req.source_drive_id,
      source: 'sharepoint_folder'
    }
  }));

const inputItems = $input.all();
const rows = inputItems.map(i => i.json);

function classify(d) {
  const nameLower = (d.file_name || '').toLowerCase();
  const ext = nameLower.split('.').pop();
  let category = 'other';
  let docType = 'other';
  let confidence = 'low';

  const rules = [
    [/proof.*address|utility|bank.statement/, 'identity', 'proof_of_address', 'high'],
    [/passport|driver.?licen|licence|id.card/, 'identity', 'photo_id', 'high'],
    [/qualif|certificate|rg146|degree|diploma/, 'cv', 'qualifications', 'high'],
    [/cv|resume|curriculum/, 'cv', 'cv_resume', 'high'],
    [/reference|referee/, 'reference', 'reference_contact', 'medium'],
    [/trust[._ -]?deed|constitution/, 'fund', 'trust_deed', 'high'],
    [/custodian/, 'fund', 'custodian_details', 'high'],
    [/administrator/, 'fund', 'fund_administrator', 'high'],
    [/auditor/, 'fund', 'auditor_details', 'high'],
    [/service[._ -]?provider|term[._ -]?sheet/, 'fund', 'service_provider_terms', 'medium'],
    [/structure|organi[sz]ational|chart/, 'fund', 'structure_chart', 'medium'],
    [/insurance|\bpi\b|cyber/, 'legal', 'insurance_details', 'medium'],
    [/tax/, 'legal', 'tax_advice', 'medium'],
    [/legal|advice|solicitor/, 'legal', 'legal_advice', 'medium'],
    [/financial|audit|accounts/, 'financial', 'audited_financials', 'medium'],
    [/memorandum|\bim\b/, 'fund', 'information_memorandum', 'medium'],
    [/mandate|strategy/, 'fund', 'investment_mandate', 'medium'],
    [/application|car|authori[sz]ed.representative/, 'corporate', 'ar_car_application_form', 'medium'],
    [/company.extract|asic|shareholder|director/, 'corporate', 'company_extract', 'medium']
  ];

  for (const [pattern, cat, type, conf] of rules) {
    if (pattern.test(nameLower)) {
      category = cat;
      docType = type;
      confidence = conf;
      break;
    }
  }

  if (category === 'other' && ['jpg', 'jpeg', 'png', 'heic'].includes(ext)) {
    category = 'identity';
    docType = 'photo_id';
    confidence = 'low';
  }

  const subfolderMap = {
    identity: '02_Identity_Documents',
    cv: '02_Identity_Documents/CV',
    reference: '04_References',
    fund: '06_DD_Report/Fund_Documents',
    legal: '06_DD_Report/Legal_Advice',
    financial: '02_Identity_Documents',
    corporate: '02_Identity_Documents',
    other: '09_Correspondence'
  };

  return {
    ...d,
    final_doc_type: docType,
    final_category: category,
    target_subfolder: subfolderMap[category] || '09_Correspondence',
    classified_by: 'rule',
    classification_confidence: confidence
  };
}

return rows.map(r => ({ json: classify(r) }));

const rows = $input.all().map(i => i.json);
const req = $('Prepare Batch Request').first().json;
const matched = rows.filter(r => r.process_status === 'matched');
const already = rows.filter(r => r.process_status === 'already_received');
const unmatched = rows.filter(r => r.process_status === 'unmatched_logged' || r.process_status === 'unmatched_existing');

return [{
  json: {
    case_id: req.case_id,
    applicant_id: req.applicant_id,
    primary_contact_name: req.primary_contact_name,
    primary_contact_email: req.primary_contact_email,
    processed_count: rows.length,
    matched_count: matched.length,
    already_count: already.length,
    unmatched_count: unmatched.length,
    matched_files: matched.map(r => ({ file_name: r.file_name, doc_type: r.final_doc_type })),
    already_files: already.map(r => ({ file_name: r.file_name, doc_type: r.final_doc_type })),
    unmatched_files: unmatched.map(r => ({ file_name: r.file_name, doc_type: r.final_doc_type })),
    batch_results: rows
  }
}];

const ctx = $input.first().json;
const batch = $('Aggregate Batch Results').first().json;
const outstanding = Array.isArray(ctx.outstanding) ? ctx.outstanding : JSON.parse(ctx.outstanding || '[]');

function list(items, fallback) {
  if (!items.length) return `<p>${fallback}</p>`;
  return '<ul>' + items.map(i => `<li>${i.file_name}${i.doc_type ? ` (${i.doc_type})` : ''}</li>`).join('') + '</ul>';
}

const outstandingHtml = outstanding.length
  ? '<p><strong>Still outstanding:</strong></p><ul>' + outstanding.map(o => `<li>${o.label}</li>`).join('') + '</ul>'
  : '<p><strong>All required documents are now received.</strong> We are progressing your application to the next stage.</p>';

const reviewHtml = batch.unmatched_count
  ? `<p><strong>Files needing staff review:</strong></p>${list(batch.unmatched_files, '')}`
  : '<p>No uploaded files require manual document-matching review.</p>';

const emailBody = `<p>Hi ${ctx.primary_contact_name},</p>
<p>We have completed a document check for your Alpha Node application.</p>
<p><strong>Newly recorded documents:</strong></p>
${list(batch.matched_files, 'No new checklist documents were recorded in this check.')}
${batch.already_count ? `<p><strong>Already on file:</strong></p>${list(batch.already_files, '')}` : ''}
${reviewHtml}
${outstandingHtml}
<p>If you have questions, please reply to this email.</p>
<p>Regards,<br>Alpha Node Team</p>`;

return [{
  json: {
    case_id: ctx.case_id,
    applicant_id: ctx.applicant_id,
    primary_contact_name: ctx.primary_contact_name,
    primary_contact_email: ctx.primary_contact_email,
    outstanding_count: outstanding.length,
    processed_count: batch.processed_count,
    matched_count: batch.matched_count,
    unmatched_count: batch.unmatched_count,
    email_subject: `Alpha Node - Document check completed for ${ctx.applicant_id}`,
    email_body: emailBody
  }
}];
